from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    extracted_groups = []  # Initialize an empty list to store the extracted groups

    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1

        if count == 0:
            extracted_groups.append(paren_string[start:i+1])  # Add each identified group to the list
            start = i + 1

    return extracted_groups  # Return the list of extracted groups

